 Certainly! Here's a JavaScript function that takes a sentence as an input and returns a new sentence where the order of the adjectives is reversed:
```javascript
function reverseAdjectiveOrder(sentence) {
  // Split the sentence into words
  const words = sentence.split(' ');

  // Initialize empty arrays for adjectives and other words
  const adjectives = [];
  const otherWords = [];

  // Identify and separate adjectives from other words
  let currentWord = '';
  for (const word of words) {
    if (isAdjective(word)) {
      adjectives.unshift(word);
    } else {
      otherWords.push(word);
      currentWord = word;
    }
  }

  // Combine the reversed adjectives and other words to form the new sentence
  const reversedAdjectives = adjectives.slice().reverse().join(' ');
  const newSentence = otherWords.join(' ') + ' ' + reversedAdjectives;

  return newSentence;
}
// Helper function to check if a word is an adjective
function isAdjective(word) {
  const adjectiveEndings = ['able', 'al', 'ic', 'ish', 'ive'];
  return adjectiveEndings.some(ending => word.endsWith(ending));
}
// Test the function with your example sentence
console.log(reverseAdjectiveOrder("Beautiful green trees are in the park")); // "Green beautiful trees are in the park"
```
This function first splits the sentence into words and separates adjectives from other words based on their ending. It then combines the reversed adjectives and other words to form the new sentence. Note that this function assumes that adjectives always come before the noun they modify in English sentences, but it may not work correctly for all cases or languages.

