```csharp
using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class RestServiceWrapper
{
    private readonly HttpClient _httpClient;
    private string _baseAddress;
    private string _authToken;

    public RestServiceWrapper(string baseAddress)
    {
        _baseAddress = baseAddress;
        _httpClient = new HttpClient();
    }

    public void SetAuthToken(string authToken)
    {
        _authToken = authToken;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
    }

    public async Task<T> GetAsync<T>(string requestUri)
    {
        using (var response = await _httpClient.GetAsync($"{_baseAddress}/{requestUri}"))
        {
            response.EnsureSuccessStatusCode();
            var responseBody = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<T>(responseBody);
        }
    }

    public async Task<T> PostAsync<T>(string requestUri, object requestData)
    {
        var json = JsonConvert.SerializeObject(requestData);
        using var content = new StringContent(json, Encoding.UTF8, "application/json");

        using var response = await _httpClient.PostAsync($"{_baseAddress}/{requestUri}", content);
        response.EnsureSuccessStatusCode();
        var responseBody = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(responseBody);
    }
}
```

