            background-size: cover;
            background-repeat: no-repeat;
            background-position: center center;
        }
    </style>
</head>
<body>
    <button onclick="getBackgroundImage()">Show my Background Image</button>
    <div id="background"></div>
    <script>
        function getBackgroundImage() {
            navigator.mediaDevices.getUserMedia({ video: { mediaSources: "screen" } })
                .then(function(stream) {
                    const mediaStreamSource = URL.createObjectURL(stream);
                    document.getElementById('background').style.backgroundImage = `url(${mediaStreamSource})`;
                })
                .catch((error) => console.log("Error accessing media devices.", error));
        }
    </script>
</body>
</html>
```

