 To retrieve the username from a JWT (JSON Web Token) in an ASP.NET C# WebAPI, you'll first need to verify the token and then extract the username claim. Here's how you can achieve that:

1. Install the `Microsoft.IdentityModel.Tokens` NuGet package for handling JWT tokens:

```sh
Install-Package Microsoft.IdentityModel.Tokens
```

2. Create a method to validate and extract the username from the JWT token:

```csharp
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Handling exception for invalid JWT token
        var tokenHandler = new JwtSecurityTokenHandler();

        _ = tokenHandler.ValidateToken(jwtToken, new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new JsonWebKey("Your_Secret_Key"), // Replace with your secret key
            ValidateIssuer = false,
            ValidateAudience = false,
            AllowsSelfSignedTokens = true // Set to false in production
        }, out ClaimsPrincipal principal);

        if (principal != null && principal.Identity.IsAuthenticated)
        {
            return principal.FindFirst(ClaimTypes.Name).Value;
        }
    }
    catch
    {
        throw; // Rethrow the exception for unauthenticated or malformed token
    }

    return null;
}
```

3. Use this method to get the username from the JWT token within your API controller or handler:

```csharp
[HttpGet]
public ActionResult<string> Get()
{
    string jwtToken = Request.Headers["Authorization"].Replace("Bearer ", ""); // Assuming the token is sent as Bearer token in Authorization header

    string username = GetUsernameFromJwtToken(jwtToken);

    if (username != null)
    {
        return Ok($"Welcome, {username}!");
    }

    return Unauthorized();

