import React from 'react';
import PropTypes from 'prop-types';

const WIDOW_THRESHOLD = 3; // number of characters to consider as threshold

function getLastLineWidth(line, fontSize) {
  const words = line.trim().split(' ');
  if (words.length === 1) return words[0].length * fontSize;
  const spaceWidth = Math.max(...words.map((word) => word.match(/[\s\u200b]+/g)?.[0]?.length || 0));
  return ((words.slice(-1).join(' ') + ' ').length - words.length + 1) * fontSize + spaceWidth;
}

function isPotentialWidow(line, lines, fontSize) {
  const width = getLastLineWidth(line, fontSize);
  const lastLineWidth = lines[lines.length - 1] ? getLastLineWidth(lines[lines.length - 1], fontSize) : 0;
  return width < lastLineWidth - WIDOW_THRESHOLD;
}

