 I'd be happy to help you write a PowerShell script for recursively checking folders to see if their Access Control Lists (ACLs) contain Security Identifiers (SIDs) that occur only in the SID history of any user or group in the Active Directory domain.

Here is a script that uses the `Get-ADUser`, `Get-Acl`, and `Select-String` cmdlets to accomplish this task:

```powershell
# Set the root folder to start the search from
$rootPath = "C:\path\to\your\folder"

# Function to get SID history of all users and groups in the domain
function Get-SidHistory {
    $users = Get-ADUser -Filter * -Properties sidHistory | ForEach-Object { $_.sidhistory }
    $groups = Get-ADGroup -Filter * -Properties sidHistory | ForEach-Object { $_.sidhistory }
    return ($users + $groups)
}

# Function to check ACLs in a given folder
function Check-FolderAcls {
    param([string]$path)

    # Get the ACL for the current folder
    $acl = Get-Acl $path

    # Initialize an empty array to store the SIDs found in the folder's ACL
    $foundSids = @()

    # Loop through each access rule in the ACL
    foreach ($accessRule in $acl.Access) {
        # Extract the SID from the IdentityReference
        $sid = $accessRule.IdentityReference.Value

        # Check if the SID exists in the SID history of any user or group in the domain
        if ((Get-SidHistory | Select-String -Pattern $sid -CaseSensitive).Count -eq 0) {
            # If not, add it to the array for output
            $foundSids += $sid
        }
    }

    # Recursively check subfolders
    Get-ChildItem $path -Directory | ForEach-Object { Check-FolderAcls $_.FullName }

    # Return the SIDs found in the current folder and its subfolders
    return $foundSids
}

# Call the function to start the search from the root folder
